import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.vXWZTEWX.js";const g=JSON.parse('{"title":"ADR 021: Adoption of Strategic \\"Honest Coverage\\" (100/60/0)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/021-quality-metrics-standard.md","filePath":"adr/021-quality-metrics-standard.md"}'),r={name:"adr/021-quality-metrics-standard.md"};function n(s,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-021-adoption-of-strategic-honest-coverage-100-60-0" tabindex="-1">ADR 021: Adoption of Strategic &quot;Honest Coverage&quot; (100/60/0) <a class="header-anchor" href="#adr-021-adoption-of-strategic-honest-coverage-100-60-0" aria-label="Permalink to &quot;ADR 021: Adoption of Strategic &quot;Honest Coverage&quot; (100/60/0)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted (Amended)</p><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><p>2026-03-04 (Updated 2026-02-02)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As the project moves closer to the Master&#39;s Thesis defense, we needed a more rigorous yet pragmatic approach to testing. A blanket &quot;80% coverage&quot; rule was insufficient because it treated critical business logic (Domain) the same as boilerplate configuration code. We needed a strategy that prioritizes business risk.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have adopted the <strong>&quot;100/60/0&quot; Strategic Coverage Standard</strong> (also known as <strong>&quot;Honest Coverage&quot;</strong>). While the initial aim was 80% global coverage, we pivoted to 60% to maintain a focus on high-fidelity testing of core logic rather than inflating metrics with boilerplate.</p><h2 id="the-standard" tabindex="-1">The Standard <a class="header-anchor" href="#the-standard" aria-label="Permalink to &quot;The Standard&quot;">​</a></h2><ol><li><strong>CORE (100%)</strong>: Domain Layer (<code>src/domain</code>). <ul><li><em>Reason</em>: Zero tolerance for logic errors in business rules. This is our &quot;Hard Base&quot;.</li></ul></li><li><strong>GLOBAL (60%)</strong>: Application, Presentation, Infrastructure. <ul><li><em>Reason</em>: We prioritize &quot;Honest Coverage&quot;. Reaching 80% in these layers would require testing thousands of lines of 3rd party adapters (Genkit, Turso) or generic boilerplate that is already validated via E2E tests. By setting the threshold at 60%, we ensure the critical orchestration logic is tested without chasing diminishing returns.</li></ul></li><li><strong>INFRA (0%)</strong>: Configuration &amp; Mocks. <ul><li><em>Reason</em>: Testing config files or mocks provides false confidence and wastes time.</li></ul></li></ol><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><ul><li><strong>Vitest Config</strong>: Thresholds are explicitly configured in <code>vitest.config.ts</code>.</li><li><strong>Husky Pre-Push</strong>: A mandatory hook runs <code>npm run test:coverage</code> before any push is allowed.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: Higher confidence in core logic. Reduced time spent testing trivial code. &quot;Honest&quot; metrics that reflect real testing effort.</li><li><strong>Negative</strong>: A 60% global coverage might seem low to external auditors who don&#39;t understand the &quot;Honest Coverage&quot; philosophy, requiring clear justification.</li></ul>',15)])])}const f=t(r,[["render",n]]);export{g as __pageData,f as default};
